<script>
 import { onMount,tick } from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import { imagePlaygroundSession,imagePlaygroundDocument,imagePlaygroundAvailability,imagePlaygroundOutputCurrent,IMAGE_PLAYGROUND_CONCEPTS } from './image-playground-state.js';
 import { imagePlaygroundMenus } from './image-playground-menus.js';
 import { createImagePlaygroundNativeView } from './image-playground-native-view.js';
 import './image-playground.css';
 let {state: imagePlaygroundState,profile,window:actualWindow=null,windowId=actualWindow?.id,controller,execute=null,oncommand=null,registerView=null,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state(''),filename=$state('My Illustration');
 let originalState,originalProfile,originalWindow,originalId,originalController,originalSession,retired=false;
 const session=$derived(imagePlaygroundSession(imagePlaygroundState,windowId)),doc=$derived(imagePlaygroundDocument(imagePlaygroundState,session?.documentId)),cap=$derived(imagePlaygroundAvailability(profile)),menus=$derived(imagePlaygroundMenus(profile,imagePlaygroundState,windowId)),pixels=$derived(imagePlaygroundOutputCurrent(doc));
 const people=$derived.by(()=>{imagePlaygroundState.revision;return controller?.targets?.().imageplayground?.find(w=>w.windowId===windowId)?.personSources??[];});
 function owned(){return !retired&&root?.isConnected===true&&imagePlaygroundState===originalState&&profile===originalProfile&&actualWindow===originalWindow&&windowId===originalId&&controller===originalController&&session===originalSession;}
 async function run(suffix,payload={}){if(!owned()||!available||!active)return;const runner=oncommand??execute,result=runner?await runner(`imageplayground.${suffix}`,{windowId},payload):await controller?.handlers?.[`imageplayground.${suffix}`]?.({windowId},payload);if(owned())message=result?.status==='applied'?'':result?.error?.message??'Original native operation unavailable.';return result;}
 async function menuClick(item){if(!owned()||!item.enabled)return;const result=await run('menu',{menuId:null});if(result?.status==='applied'&&owned())await run(item.command.slice('imageplayground.'.length),item.payload);}
 function keyboard(e){if(!owned()||!available||!active)return;const typing=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if((e.ctrlKey||e.metaKey)&&!e.altKey){const k=e.key.toLowerCase();if(k==='s'){e.preventDefault();run(e.shiftKey?'panel':'save',e.shiftKey?{panel:'save'}:{});}else if(k==='o'){e.preventDefault();run('open');}else if(k==='n'){e.preventDefault();run(e.shiftKey?'window.new':'new');}else if(k==='z'&&!typing){e.preventDefault();run(e.shiftKey?'redo':'undo');}else if(k==='c'&&!typing){e.preventDefault();run('copy');}}if(e.key==='Escape'){run(session?.menu?'menu':'panel',session?.menu?{menuId:null}:{panel:'none'});}if(e.key==='Enter'&&e.target.dataset.imagePlaygroundControl==='prompt'&&!e.shiftKey){e.preventDefault();run('generate');}}
 onMount(()=>{originalState=imagePlaygroundState;originalProfile=profile;originalWindow=actualWindow;originalId=windowId;originalController=controller;originalSession=session;const view=createImagePlaygroundNativeView({getRoot:()=>root,getState:()=>imagePlaygroundState,getSession:()=>session,getProfile:()=>profile,getWindow:()=>actualWindow,getController:()=>controller,windowId,available:()=>owned()&&available&&active,tick,getMenus:()=>imagePlaygroundMenus(profile,imagePlaygroundState,windowId)});registerView?.(windowId,view);return()=>{retired=true;view.destroy();registerView?.(originalId,null,view);};});
</script>
<section bind:this={root} class="image-playground-app" class:golden={cap.golden} class:windows={cap.windows} class:legacy={cap.legacy} class:inactive={!active} data-image-playground-window-id={windowId} data-profile={profile.id} role="region" aria-label={cap.label} tabindex="-1" onkeydown={keyboard}>
 <header class="ip-titlebar">
 {#if !cap.windows}<WindowControls active={active} onclose={()=>run('close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}
 <strong>{cap.label}</strong><span>Local procedural studio · not AI</span>
 {#if cap.windows}<button aria-label="Minimize" data-image-playground-control="window:minimize" disabled={!active||!available||typeof controls.onminimize!=='function'} onclick={controls.onminimize}>−</button><button aria-label="Maximize or restore" data-image-playground-control="window:zoom" disabled={!active||!available||typeof controls.onzoom!=='function'} onclick={controls.onzoom}>□</button><button aria-label="Close" data-image-playground-control="window:close" onclick={()=>run('close')}>×</button>{/if}
 </header>
 {#if cap.windows}<nav class="ip-local-menubar" aria-label="Application menus">{#each menus as menu}<button data-image-playground-control={`menu:${menu.id}`} onclick={()=>run('menu',{menuId:session?.menu===menu.id?null:menu.id})}>{menu.label}</button>{/each}</nav>{/if}
 {#if session?.menu}<div class="ip-menu" role="menu">{#each menus.find(m=>m.id===session.menu)?.items??[] as item}<button role="menuitem" data-image-playground-control={`menuitem:${item.id}`} disabled={!item.enabled} onclick={()=>menuClick(item)}>{item.checked?'✓ ':''}{item.label}</button>{/each}</div>{/if}
 <div class="ip-toolbar" inert={!active||!available||session?.panel!=='none'}>
 <button data-image-playground-control="new" onclick={()=>run('new')}>＋ New Image</button><button data-image-playground-control="open" onclick={()=>run('open')}>Open Recipe…</button><span></span><button data-image-playground-control="copy" disabled={!pixels} onclick={()=>run('copy')}>Copy Image</button><button data-image-playground-control="share" disabled={!pixels} onclick={()=>run('share')}>Share…</button><button data-image-playground-control="export" disabled={!pixels} onclick={()=>run('panel',{panel:'export'})}>Export PNG</button><button class="ip-primary" data-image-playground-control="save" disabled={!doc} onclick={()=>run('save')}>Save Recipe</button>
 </div>
 <div class="ip-workspace" inert={!active||!available||session?.panel!=='none'}>
 <aside class="ip-gallery" tabindex="0" data-image-playground-area="gallery" data-image-playground-control="gallery" aria-label="Image gallery"><h2>My Images <small>{imagePlaygroundState.documents.length}</small></h2>
 {#each imagePlaygroundState.documents as d (d.id)}<button class:selected={d===doc} class="ip-gallery-image" data-image-playground-control={`document:${d.id}`} onclick={()=>run('document.select',{documentId:d.id})}>{#if d.png}<img alt={`Local procedural output: ${d.recipe.title}`} src={d.png}/>{:else}<div class="ip-unrendered">Not rendered</div>{/if}<span>{d.recipe.title}{d.dirty?' •':''}</span><small>{d.recipe.style} · seed {d.recipe.seed}</small></button>{/each}
 {#if !imagePlaygroundState.documents.length}<p>Your local gallery is empty. Create an image to begin.</p>{/if}<button data-image-playground-control="new-window" onclick={()=>run('window.new')}>New Window</button>
 </aside>
 <main class="ip-editor" data-image-playground-area="editor">
 {#if doc}<div class="ip-preview-heading"><input aria-label="Image title" data-image-playground-control="title" maxlength="128" value={doc.recipe.title} onchange={e=>run('recipe.update',{title:e.currentTarget.value})}/><span>{doc.dirty?'Edited':doc.fileId?'Saved recipe':'Local image'}</span></div>
 <div class="ip-preview">{#if doc.png}<img alt={`Actual locally rendered canvas: ${doc.recipe.title}`} src={doc.png}/>{:else}<div class="ip-empty-preview"><div class="ip-orbit">○</div><h2>Make something your own.</h2><p>Describe a supported scene below.<br/>Shapes, colors and composition are drawn locally.</p></div>{/if}{#if doc.png&&!pixels}<div class="ip-outdated">Recipe edited — render to update the actual pixels.</div>{/if}</div>
 <div class="ip-variation"><button data-image-playground-control="variation:previous" onclick={()=>run('variation',{direction:'previous'})}>‹ Previous</button><span>{doc.recipe.style} · seed {doc.recipe.seed}</span><button data-image-playground-control="variation:next" onclick={()=>run('variation',{direction:'next'})}>Next ›</button></div>
 <div class="ip-description"><label for={`ip-prompt-${windowId}`}>Describe an image</label><textarea id={`ip-prompt-${windowId}`} data-image-playground-control="prompt" maxlength="1024" rows="2" value={doc.recipe.prompt} oninput={e=>run('recipe.update',{prompt:e.currentTarget.value})} placeholder="A blue robot in a forest with stars"></textarea><button class="ip-primary" data-image-playground-control="generate" onclick={()=>run('generate')}>Render Locally</button></div>
 <p class="ip-limit">Only documented concept and color words are supported. Unknown requests reject; no model or AI service is contacted.</p>
 {#if doc.variations.length}<details class="ip-history"><summary>Rendered recipe history ({doc.variations.length}/12)</summary>{#each doc.variations as recipe,index}<button data-image-playground-control={`history:${index}`} onclick={()=>run('history.restore',{index})}>{recipe.style} · seed {recipe.seed} · {recipe.prompt||recipe.concepts.join(', ')}</button>{/each}</details>{/if}
 {:else}<div class="ip-welcome"><div class="ip-orbit">○</div><h1>Image Playground</h1><p>A small studio for authored local illustrations.<br/>Real canvas pixels, no artificial intelligence.</p><button class="ip-primary" data-image-playground-control="start" onclick={()=>run('new')}>New Image</button><p>Native Image Playground first appeared in macOS 15.2.<br/>This implementation is a clearly disclosed local equivalent.</p></div>{/if}
 </main>
 {#if doc}<aside class="ip-concepts" data-image-playground-area="concepts"><h2>Style</h2><div class="ip-styles">{#each ['animation','illustration','sketch'] as style}<button class:selected={doc.recipe.style===style} data-image-playground-control={`style:${style}`} onclick={()=>run('recipe.update',{style})}><span class={`ip-style-icon ${style}`}>{style==='sketch'?'╱╱':style==='animation'?'●':'◆'}</span>{style[0].toUpperCase()+style.slice(1)}</button>{/each}</div><small>Procedural interpretations, not native AI styles.</small>
 <h2>Concepts</h2><p>Combine up to seven input elements.</p><div class="ip-concept-list">{#each IMAGE_PLAYGROUND_CONCEPTS as concept}<button class:selected={doc.recipe.concepts.includes(concept)} data-image-playground-control={`concept:${concept}`} onclick={()=>run('concept.toggle',{concept})}>{concept}</button>{/each}</div>
 <h2>Starting Point</h2><button data-image-playground-control="people" onclick={()=>run('panel',{panel:'people'})}>{doc.recipe.person?doc.recipe.person.name:'Choose Person from Photos…'}</button>{#if doc.recipe.person}<button data-image-playground-control="people:clear" onclick={()=>run('people.clear')}>Remove Photo Source</button>{/if}<p>Permission-authorized photo collage. No face recognition or generated likeness.</p>
 <label>Variation seed<input data-image-playground-control="seed" type="number" min="0" max="2147483647" value={doc.recipe.seed} onchange={e=>run('recipe.update',{seed:Number(e.currentTarget.value)})}/></label>
 <div class="ip-edit-buttons"><button data-image-playground-control="undo" disabled={!doc.undo.length} onclick={()=>run('undo')}>Undo</button><button data-image-playground-control="redo" disabled={!doc.redo.length} onclick={()=>run('redo')}>Redo</button></div><button data-image-playground-control="same-image-window" onclick={()=>run('window.new',{documentId:doc.id})}>Open in New Window</button><button data-image-playground-control="delete" disabled={doc.dirty} onclick={()=>run('document.delete')}>Delete Saved Gallery Image</button>
 </aside>{/if}
 </div>
 {#if session?.panel!=='none'}<div class="ip-sheet-backdrop"><section class="ip-sheet" role="dialog" aria-modal="true" aria-label={session?.panel==='people'?'Choose Person':session?.panel==='close'?'Save Changes':'Image Playground'}>
 {#if session?.panel==='people'}<h2>Choose a Person from Photos</h2><p>Only actual visible Photos items with named people are listed after explicit scene Privacy permission. The selected photo becomes a real circular collage, never an AI likeness.</p><div class="ip-people">{#each people as person}<button data-image-playground-control={`person:${person.photoId}:${person.name}`} onclick={()=>run('people.select',person)}><strong>{person.name}</strong><small>{person.photoId}</small></button>{/each}</div>{#if !people.length}<p>No permission-authorized named people available. In Photos, name a person on an image; in scene Privacy settings, allow Image Playground Photos access. Missing permission denies access.</p>{/if}<button data-image-playground-control="people:done" onclick={()=>run('panel',{panel:'none'})}>Cancel</button>
 {:else if session?.panel==='save'||session?.panel==='export'}<h2>{session.panel==='save'?'Save Custom Editable Recipe':'Export Actual PNG'}</h2><p>{session.panel==='save'?'The custom .jip.json format stores prompt, concepts, style, seed and canonical Photos references. It is not an Apple proprietary format; Photos references require the same original permitted library.':'Exports the current genuine 512 × 512 canvas pixels to shared Documents.'}</p><label>Name<input data-image-playground-control="filename" maxlength="240" bind:value={filename}/></label><div class="ip-sheet-actions"><button data-image-playground-control="file:cancel" onclick={()=>run('panel',{panel:'none'})}>Cancel</button><button class="ip-primary" data-image-playground-control="file:save" disabled={!filename.trim()} onclick={()=>run(session.panel==='save'?'save':'export',session.panel==='save'?{name:filename,saveAs:true}:{name:filename})}>{session.panel==='save'?'Save .jip.json':'Export .png'}</button></div>
 {:else if session?.panel==='close'}<h2>Save changes to “{doc?.recipe.title}”?</h2><p>Save writes a clearly custom editable recipe. Discard restores the saved recipe in every window viewing this image.</p><div class="ip-sheet-actions"><button data-image-playground-control="close:discard" onclick={()=>run('close',{decision:'discard'})}>Don't Save</button><button data-image-playground-control="close:cancel" onclick={()=>run('close',{decision:'cancel'})}>Cancel</button><button class="ip-primary" data-image-playground-control="close:save" onclick={()=>run('close',{decision:'save'})}>Save</button></div>
 {:else}<h2>About this local playground</h2><p>{cap.disclosure}</p><p>Supported subjects: mountains, forest, ocean, city, flowers, cat, rabbit and robot. Add sunset, night, stars, rainbow, hat or glasses. Supported colors: red, orange, yellow, green, blue, purple, pink, white and black. Example: “A blue robot in a forest with stars”.</p><p>Prompt, concepts and seed determine real geometry and color. Animation uses shaded backgrounds; Illustration uses colorblocking; Sketch uses outlines and seeded hatching. There is no AI/model, networking, cloud gallery or likeness generation. Photos person selection is an explicit permission-gated collage of actual source pixels.</p><p>Save/Open uses custom .jip.json recipes. Export, Copy Image and Share use genuine PNG bytes through the single scene destination authority. Gallery state, undo/redo and rendered recipe history are bounded. Native windows share actual gallery documents.</p><button data-image-playground-control="help:done" onclick={()=>run('panel',{panel:'none'})}>Done</button>{/if}
 {#if message}<p class="ip-error" role="alert">{message}</p>{/if}</section></div>{/if}
 <footer class="ip-status" role="status"><span>{message||cap.disclosure}</span><button data-image-playground-control="help" onclick={()=>run('panel',{panel:'help'})}>Help</button></footer>
</section>
